llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Tocotrienol, a lipophilic isoprenoid with a polar ring similar in physicochemical character to the query polyprenyl quinone, is reported to have poor oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lycopene, a long-chain lipophilic carotenoid, showed only about 1.2% systemic availability after an oral dose dispersed in oil in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene from tomato paste showed only 0.17% of the dose in the circulation, indicating very low systemic availability for a large lipophilic polyene.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "After steamed and pureed tomato, only about 0.2–0.3% of lycopene was detected in the circulation, supporting low oral bioavailability for large lipophilic isoprenoid-type molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A deuterated lycopene study in humans estimated bioavailability at 1.2%, reinforcing the pattern of low systemic availability for long-chain lipophilic carotenoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Phytoene was estimated at 58.5% bioavailability in humans, providing a high-bioavailability example among polyisoprenoids, but its lack of a polar quinone/chromanol head group limits transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Labeled all-trans lycopene was estimated at 23.2% bioavailability in one human compartmental-model study, which is above the 20% threshold but is an outlier relative to direct systemic-availability measurements and less transferable to the quinone-containing query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a long-chain polyprenyl quinone (ubiquinone-type). The most transferable evidence from tocotrienol and lycopene indicates poor oral bioavailability for large lipophilic isoprenoid/quinone-type molecules. The high phytoene and labeled-lycopene estimates are less transferable due to different head-group chemistry and measurement approaches. Therefore, F >= 20% is not supported; predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact ubiquinone/polyprenyl quinone query molecule is provided.",
    "Formulation, food effects, and particle size strongly affect absorption of highly lipophilic quinones, but no query-specific formulation data are available.",
    "The high phytoene and labeled-lycopene estimates rely on compartmental modeling rather than direct AUC comparison to intravenous dosing, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

